import{_ as s,o as t,c as r,a3 as o}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"问卷提建议存储处","description":"","frontmatter":{"translationSource":{"title":"问卷提建议存储处","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=pY03IOJsZdm5I2dQLe59Yi","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/repository-of-survey-suggestions"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/repository-of-survey-suggestions"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/repository-of-survey-suggestions"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/repository-of-survey-suggestions"}]]},"headers":[],"relativePath":"zh/repository-of-survey-suggestions.md","filePath":"zh/page-pY03IOJsZdm5I2dQLe59Yi.md"}'),a={name:"zh/repository-of-survey-suggestions.md"};function i(d,e,p,n,l,c){return t(),r("div",null,[...e[0]||(e[0]=[o('<div class="logistics-content"><span class="logistics-source-anchor" id="问卷提建议存储处" aria-hidden="true"></span><h1 id="问卷提建议存储处" tabindex="-1">问卷提建议存储处 <a class="header-anchor" href="#问卷提建议存储处" aria-label="Permalink to &quot;问卷提建议存储处&quot;">​</a></h1><blockquote><p>源页面 ID：<code>pY03IOJsZdm5I2dQLe59Yi</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=pY03IOJsZdm5I2dQLe59Yi" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>很多人临到填问卷的时候就忘记了平时时不时说要写上去的，直到交完了才反应过来，为了减少这些问题，可以往这里写上问卷想提的内容，填问卷的时候直接从这里复制。</p><details><summary>jnk</summary><p>修改培养总览，给技能与天赋加一个不点普通攻击技能的选项。基质蚀刻增加多选一键用于蚀刻的功能。蓝图广场，将分享的蓝图全部公开随意查看，让人屎里掏金。</p></details><details><summary>言</summary><p><strong>bug反馈类</strong></p><p>多原料反应切换8次卡1s需要被修复</p><p>取货口输出与轮询相去甚远需要被修复；存货口还算好用</p><p>自动种植机在收获时会吞物品，参考视频：【终末地】以防你不知道自动收割机会偷吃土豆】<a href="https://www.bilibili.com/video/BV1PLJ86VEnr?vd_source=bf73afe506171ce1f2c1a4732d9d4bde" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1PLJ86VEnr?vd_source=bf73afe506171ce1f2c1a4732d9d4bde</a></p><p><strong>建议类</strong></p><p>蓝图只能保存50m以内的无法一次性保存主基地的暗管，使得蓝图分享变得困难。而管道上限的限制会进一步加大暗管需求，希望能增加到80m以覆盖主基地</p><p>在修改基建时很容易误删与外部暗管连接的暗管，希望增加暗管的锁定功能，或者干脆所有设备都能手动锁定，那应该是最好的</p><p>希望鸟瞰模式的暗管交互体验优化，其一是需要俯瞰视角的暗管连接；其二是这种暗管连接的显示需要足够有条理。根据我的建造体验给出一个方案雏形（或者说通过这个方案来精确表达我的想法）：鸟瞰模式下可让指定暗管显示连接/不显示连接，同时可存在多个连接被显示</p><p>请实时显示管道物流元件上限/设备上限/管道上限。从玩法本身而言我不排斥不太过过分的上限制约，因为这使得设计者需要优化架构底层逻辑以减少物流元件等受制约因素的使用，在工厂游戏中算是相当有特色的需求，但是不实时显示非常恶劣，试想设计者到总装才发现自己的设计因为这些上限无法落地，显然是非常糟糕的体验</p><p>在工业用地中使用息壤供电桩会造成基地外电线意外断连，比如本来外面的电线是接协议核心的，一旦连接之后无论怎么动协议核心都不影响，但是使用息壤供电桩之后可能会取代协议核心与外部电线进行连接，而这根供电桩如果在修改基建中被删除就会造成外部电线断连。虽然不是bug但是这样的逻辑就很麻烦，希望能有所优化</p><p>可保存蓝图数目太少且没有分类/排序这种交互功能</p><p>希望增加液气存取线-液气仓储或者别的方法使得液气资源不成为对布局的限制，虽然这样的限制在现实和其他工厂游戏中很常见但是在终末地基建中我主要感受到的是它对布局过分的作茧自缚——对布局优化的鼓励事实上只靠占地制约/管道件制约就能达到效果。如果能解开这个限制那对较为深度的基建玩家而言创作将变得灵活很多，同时对于浅度玩家也能避免外部液气资源连接有误造成的可抄性地狱。</p></details><details><summary>展开内容</summary></details></div>',1)])])}const f=s(a,[["render",i]]);export{h as __pageData,f as default};
